#include <bits/stdc++.h>
using namespace std;
int main(){int n;while(cin>>n&&n){map<array<int,5>,int>m;int mx=0;for(int i=0;i<n;i++){array<int,5>a;for(int &x:a)cin>>x;sort(a.begin(),a.end());mx=max(mx,++m[a]);}int answer=0;for(auto [a,count]:m)if(count==mx)answer+=count;cout<<answer<<"\n";}}

